test('vatSummary returns empty array for no invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary returns empty array for only draft invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-01',
      status: 'draft',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  assert.deepEqual(result, []);
});

test('vatSummary single invoice with single VAT rate', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
